	@Test
	void ordinaryPreparedEvaluationDoesNotLookUpAllocationStateAsRowsIncrease() {
		String uri = "urn:test:blank-node-effects:identity";
		var inputNode = VF.createBNode();
		var row = new MapBindingSet();
		row.addBinding("value", inputNode);
		var function = new Scalar(uri, BlankNodeEffects.NONE, (factory, args) -> args[0]);
		var registry = FunctionRegistry.getInstance();
		var previous = registry.add(function);
		try {
			var context = new CountingContext();
			var assignment = new BindingSetAssignment();
			assignment.setBindingSets(IntStream.range(0, 1_000_000).<BindingSet>mapToObj(i -> row).toList());
			var expression = new Extension(assignment,
					new ExtensionElem(new FunctionCall(uri, Var.of("value")), "out"));
			var step = strategy().precompile(expression, context);
			context.scopeReads.set(0);
			for (int count : List.of(10, 1_000_000)) {
				try (var rows = step.evaluate(EmptyBindingSet.getInstance())) {
					for (int i = 0; i < count; i++) {
						assertSame(inputNode, rows.next().getValue("out"));
					}
				}
				assertEquals(1, function.declarations.get());
				assertEquals(0, context.scopeReads.get());
			}
		} finally {
			registry.remove(function);
			previous.ifPresent(registry::add);
		}
	}

