	@Test
	void preparedNestedLabelledCallbackReturningLiteralRetainsItsExactImplementation() {
		String uri = "urn:test:blank-node-effects:labelled";
		var labels = new ArrayList<Value>();
		var labelled = new Scalar(uri, BlankNodeEffects.LABELLED, (factory, args) -> {
			var label = factory.createBNode("label");
			assertEquals(label, factory.createBNode("label"));
			labels.add(label);
			return factory.createLiteral(7);
		});
		var replacement = new Scalar(uri, BlankNodeEffects.NONE, (factory, args) -> factory.createLiteral(false));
		var registry = FunctionRegistry.getInstance();
		var previous = registry.add(labelled);
		try {
			var context = new QueryEvaluationContext.Minimal(null);
			var input = repeatedRows(2);
			// This override compiles its child through the public entry, as existing extensions do.
			var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null) {
				@Override
				protected QueryValueEvaluationStep prepare(Not node, QueryEvaluationContext context) {
					QueryValueEvaluationStep child = precompile(node.getArg(), context);
					return row -> VF.createLiteral(!((Literal) child.evaluate(row)).booleanValue());
				}
			};
			var algebra = new Extension(input,
					new ExtensionElem(new Not(new IsLiteral(new FunctionCall(uri))), "handled"),
					new ExtensionElem(new BNodeGenerator(new ValueConstant(VF.createLiteral("label"))), "label"));
			var prepared = strategy.precompile(algebra, context);
			registry.add(replacement);
			assertTrue(labels.isEmpty(), "a deterministic declaration must not fold blank-node work");
			try (var rows = prepared.evaluate(EmptyBindingSet.getInstance())) {
				assertEquals(labelsAfterNext(rows, labels, 0), labels.get(0));
				assertEquals(labelsAfterNext(rows, labels, 1), labels.get(1));
				assertFalse(rows.hasNext());
			}
			assertNotEquals(labels.get(0), labels.get(1));
			assertEquals(1, labelled.declarations.get());
			assertEquals(0, replacement.declarations.get());
		} finally {
			registry.remove(replacement);
			previous.ifPresent(registry::add);
		}
	}

	@Test
	void foreignPreparedRunsShareAliasesWithinEachRunAndIsolateConcurrentRuns() throws Exception {
		String firstUri = "urn:test:blank-node-effects:foreign-a";
		String secondUri = "urn:test:blank-node-effects:foreign-b";
		String nestedUri = "urn:test:blank-node-effects:foreign-nested";
		var effects = BlankNodeEffects.foreign(new Object());
		var first = new Scalar(firstUri, effects, (factory, args) -> factory.createBNode("same"));
		var nested = new Scalar(nestedUri, effects, (factory, args) -> factory.createBNode("same"));
		var nestedPlan = new AtomicReference<QueryEvaluationStep>();
		var second = new Scalar(secondUri, BlankNodeEffects.NONE, (factory, args) -> {
			try (var rows = nestedPlan.get().evaluate(EmptyBindingSet.getInstance())) {
				return rows.next().getValue("out");
			}
		});
		var registry = FunctionRegistry.getInstance();
		var previousFirst = registry.add(first);
		var previousSecond = registry.add(second);
		var previousNested = registry.add(nested);
		try {
			var strategy = strategy();
			var context = new QueryEvaluationContext.Minimal(null);
			nestedPlan.set(strategy.precompile(new Extension(repeatedRows(1),
					new ExtensionElem(new FunctionCall(nestedUri), "out")), context));
			var expression = new Extension(repeatedRows(4),
					new ExtensionElem(new FunctionCall(firstUri), "first"),
					new ExtensionElem(new FunctionCall(secondUri, Var.of("first")), "second"));
			var step = strategy.precompile(expression, context);
			var firstRun = readAliases(step.evaluate(EmptyBindingSet.getInstance()));
			try (var pool = Executors.newFixedThreadPool(2)) {
				var a = pool.submit(() -> readAliases(step.evaluate(EmptyBindingSet.getInstance())));
				var b = pool.submit(() -> readAliases(step.evaluate(EmptyBindingSet.getInstance())));
				assertEquals(3, Set.of(firstRun, a.get(), b.get()).size());
			}
			assertEquals(1, first.declarations.get());
			assertEquals(1, second.declarations.get());
			assertEquals(1, nested.declarations.get());
		} finally {
			registry.remove(first);
			registry.remove(second);
			registry.remove(nested);
			previousFirst.ifPresent(registry::add);
			previousSecond.ifPresent(registry::add);
			previousNested.ifPresent(registry::add);
		}
	}

