	@Test
	void delayedGroupResolvesTheReplacementFactoryAndItsFreshDeclarationTogether() {
		var first = new FreshAggregateFactory("urn:test:blank-node-effects:aggregate");
		var replacement = new FreshAggregateFactory(first.getIri());
		var registry = CustomAggregateFunctionRegistry.getInstance();
		var previous = registry.add(first);
		try {
			var group = new Group(repeatedRows(2));
			group.addGroupElement(new GroupElem("out",
					new AggregateFunctionCall(List.of(new ValueConstant(VF.createLiteral(1))), first.getIri(), false)));
			var step = strategy().precompile(group, new QueryEvaluationContext.Minimal(null));
			try (var unopened = step.evaluate(EmptyBindingSet.getInstance())) {
				assertEquals(0, first.declarations.get());
			}
			registry.add(replacement);
			Value firstRun;
			try (var rows = step.evaluate(EmptyBindingSet.getInstance())) {
				firstRun = rows.next().getValue("out");
				assertTrue(firstRun.isBNode());
				assertFalse(rows.hasNext());
			}
			try (var rows = step.evaluate(EmptyBindingSet.getInstance())) {
				Value secondRun = rows.next().getValue("out");
				assertTrue(secondRun.isBNode());
				assertNotEquals(firstRun, secondRun);
			}
			assertEquals(0, first.declarations.get());
			assertEquals(2, replacement.declarations.get());
		} finally {
			registry.remove(replacement);
			previous.ifPresent(registry::add);
		}
	}

	@Test
	void independentlyDelayedSiblingGroupsUseTheSameAliasNamespaceForOneRun() {
		var factory = new ForeignAggregateFactory();
		var registry = CustomAggregateFunctionRegistry.getInstance();
		var previous = registry.add(factory);
		try {
			var left = new Group(repeatedRows(2));
			var right = new Group(repeatedRows(2));
			var leftElement = new GroupElem("left", new Count(null));
			var rightElement = new GroupElem("right", new Count(null));
			left.addGroupElement(leftElement);
			right.addGroupElement(rightElement);
			var step = strategy().precompile(new Union(left, right), new QueryEvaluationContext.Minimal(null));
			// The algebra allows GROUP's collectors to be installed after the member operand is prepared.
			leftElement.setOperator(new AggregateFunctionCall(List.of(new ValueConstant(VF.createLiteral(1))),
					factory.getIri(), false));
			rightElement.setOperator(new AggregateFunctionCall(List.of(new ValueConstant(VF.createLiteral(1))),
					factory.getIri(), false));
			Value firstRun = null;
			for (int run = 0; run < 2; run++) {
				try (var rows = step.evaluate(EmptyBindingSet.getInstance())) {
					Value alias = rows.next().getValue("left");
					assertEquals(alias, rows.next().getValue("right"));
					assertFalse(rows.hasNext());
					if (run == 0) {
						firstRun = alias;
					} else {
						assertNotEquals(firstRun, alias);
					}
				}
			}
		} finally {
			registry.remove(factory);
			previous.ifPresent(registry::add);
		}
	}

